import type { CSSProperties } from "react";

// Hand-inked decorations. Illustrations are the same SVGs the iOS app ships
// (generated by ios/Tools/illustrations/generate.py, copied to public/).

export type IllustrationName =
  | "ill-beaker"
  | "ill-compress"
  | "ill-empty-box"
  | "ill-lock"
  | "ill-phone-sparkle"
  | "ill-photo"
  | "ill-piggy"
  | "ill-reset"
  | "ill-screenshot"
  | "ill-shield-check"
  | "ill-stack-large"
  | "ill-stack-small"
  | "ill-trash"
  | "ill-umbrella"
  | "ill-video";

export function Illustration({
  name,
  size = 96,
  className,
  style,
  priority,
}: {
  name: string;
  size?: number;
  className?: string;
  style?: CSSProperties;
  priority?: boolean;
}) {
  return (
    // Plain <img>: these are tiny vector files, so next/image adds nothing.
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={`/illustrations/${name}.svg`}
      alt=""
      aria-hidden="true"
      width={size}
      height={size}
      loading={priority ? "eager" : "lazy"}
      decoding="async"
      className={className}
      style={style}
    />
  );
}

/** A loose marker underline that draws itself in. */
export function Scribble({ className, delay = 450 }: { className?: string; delay?: number }) {
  return (
    <svg
      viewBox="0 0 300 24"
      preserveAspectRatio="none"
      aria-hidden="true"
      className={`draw-now ${className ?? ""}`}
      style={{ "--len": 340, "--draw-delay": delay } as CSSProperties}
    >
      <path
        d="M4 15c40-7 92-11 146-10 52 1 98 4 146 9M22 20c58-5 132-7 236-3"
        fill="none"
        stroke="currentColor"
        strokeWidth="5"
        strokeLinecap="round"
      />
    </svg>
  );
}

/** A curly hand-drawn arrow for annotations. Points down-left by default. */
export function InkArrow({ className, style }: { className?: string; style?: CSSProperties }) {
  return (
    <svg
      viewBox="0 0 120 90"
      aria-hidden="true"
      className={`draw ${className ?? ""}`}
      style={{ "--len": 260, ...style } as CSSProperties}
    >
      <path
        d="M112 8c-22 4-44 16-52 34-6 14 6 22 14 14 8-9-6-20-22-14-18 7-30 24-38 40"
        fill="none"
        stroke="currentColor"
        strokeWidth="3.2"
        strokeLinecap="round"
      />
      <path
        d="M10 58l3 25 22-11"
        fill="none"
        stroke="currentColor"
        strokeWidth="3.2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** Small sparkle ticks, like the ones around the icons. */
export function Sparks({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 40 40" aria-hidden="true" className={className}>
      <g stroke="currentColor" strokeWidth="3" strokeLinecap="round">
        <path d="M20 3v9M4 14l7 5M36 14l-7 5" />
      </g>
    </svg>
  );
}

/** Hand-drawn strike-through for crossed-out claims. */
export function Strike({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 200 20"
      preserveAspectRatio="none"
      aria-hidden="true"
      className={`draw pointer-events-none ${className ?? ""}`}
      style={{ "--len": 230, "--draw-delay": 350 } as CSSProperties}
    >
      <path
        d="M3 12c50-5 120-8 194-3"
        fill="none"
        stroke="var(--tomato)"
        strokeWidth="4"
        strokeLinecap="round"
      />
    </svg>
  );
}
